	/**
	 * この画面のステータスを設定します。
	 *
	 * @param status ステータス
	 */
	public void setStatus(String status) {
		super.setStatus(status);
		if (SRCH_HDR.equals(status)) {
			setSRCH_HDRStatus();
		}
		else if (REF_HDR.equals(status)) {
			setREF_HDRStatus();
		}
		else if (SRCH_DTL.equals(status)) {
			setSRCH_DTLStatus();
		}
		else if (REF_DTL.equals(status)) {
			setREF_DTLStatus();
		}
		else if (SRCH_SHIP_SCHD.equals(status)) {
			setSRCH_SHIP_SCHDStatus();
		}
		else if (REF_SHIP_SCHD.equals(status)) {
			setREF_SHIP_SCHDStatus();
		}
		else if (IMP_FILE.equals(status)) {
			setIMP_FILEStatus();
		}
		else if (INS.equals(status)) {
			setINSStatus();
		}
		else if (FIX_I.equals(status)) {
			setFIX_IStatus();
		}
	}

